SET source_codes = 'ب د ع',
    content_ar = 'طلحة بن عبيد الله بن عثمان ابن عمرو بن كعب بن سعد بن تيم بن مرة بن كعب بن لؤي بن غالب بن فهر بن مالك بن النضر بن كنانة أبو محمد القرشي التيمي وأمه الصعبة بنت عبد الله بن مالك الحضرمية يعرف بطلحة الخير وطلحة الفياض وهو من السابقين الأولين إلى الإسلام دعاه أبو بكر الصديق إلى الإسلام فأخذه ودخل به على رسول الله صلى الله عليه وسلم فلما أسلم هو وأبو بكر أخذهما نوفل بن خويلد بن العدوية فشدهما في حبل واحد ولم يمنعهما بنو تيم وكان نوفل أشد قريش فلذلك كان أبو بكر وطلحة يسميان القرينان وقيل إن الذي قرنهما عثمان بن عبيد الله أخو طلحة فشدهما ليمنعهما عن الصلاة وعن دينهما فلم يجيباه فلم يرعهما إلا وهما مطلقان يصليان ولما أسلم طلحة والزبير آخى رسول الله صلى الله عليه وسلم بينهما بمكة قبل الهجرة فلما هاجر المسلمون إلى المدينة آخى رسول الله صلى الله عليه وسلم بين طلحة وبين أبي أيوب الأنصاري وهو أحد العشرة المشهود لهم بالجنة وأحد أصحاب الشورى ولم يشهد بدرا لانه كان بالشام فقدم بعد رجوع رسول الله صلى الله عليه وسلم من بدر فكلم رسول الله صلى الله عليه وسلم في سهمه فقال لك سهمك قال وأجرى قال وأجرك فقيل كان في الشام تاجرا وقيل بل أرسله رسول الله صلى الله عليه وسلم ومعه سعيد بن زيد إلى طريق الشام يتجسسان الأخبار ثم رجعا إلى المدينة وهذا أصح ولولا ذلك لم يطلب سهمه وأجره وشهد أحدا وما بعدها من المشاهد وبايع بيعة الرضوان وأبلى يوم أحد بلاء عظيما ووقى رسول الله صلى الله عليه وسلم بنفسه واتقى عنه النبل بيده حتى شلت إصبعه وضرب ضربة على رأسه وحمل رسول الله صلى الله عليه وسلم على ظهره حتى صعد الصخرة أخبرنا أبو الفرج بن أبي الرجاء الأصبهاني إجازة بإسناده إلى أبي بكر بن أبي عاصم حدثنا الحسن بن علي حدثنا سليمان بن أيوب بن سليمان بن عيسى بن موسى بن طلحة بن عبيد الله أخبرني أبي عن جدي عن موسى بن طلحة عن أبيه طلحة قال سماني رسول الله صلى الله عليه وسلم يوم أحد طلحة الخير ويوم العسرة طلحة الفياض ويوم حنين طلحة الجود أخبرنا إبراهيم بن محمد بن مهران الشافعي وغير واحد بإسنادهم إلى أبي عيسى محمد بن عيسى قال حدثنا أبو سعيد الأشج حدثنا يونس بن بكير عن محمد بن إسحاق عن يحيى بن عباد بن عبد الله بن الزبير عن أبيه عن جده عبد الله بن
الزبير عن الزبير قال كان على رسول الله صلى الله عليه وسلم يوم أحد درعان فنهض إلى الصخرة فلم يستطع فأقعد تحته طلحة فصعد النبي صلى الله عليه وسلم حتى استوى على الصخرة قال فسمعت رسول الله صلى الله عليه وسلم يقول أوجب طلحة قال وحدثنا أبو سعيد الأشج حدثنا أبو عبد الرحمن بن منصور العنزي اسمه النضر عن عقبة بن علقمة اليشكري قال سمعت علي بن أبي طالب يقول سمعت أذني رسول الله صلى الله عليه وسلم يقول طلحة والزبير جاراي في الجنة أخبرنا أبو بكر ممشاد بن عمر بن العويس البناء أخبرنا أبو العباس أحمد بن أبي غالب بن الطلابة أخبرنا أبو القاسم عبد العزيز بن علي بن أحمد بن الحسين الأنماطي أخبرنا أبو طاهر المخلص حدثنا عبد الله بن محمد البغوي حدثنا داود بن رشيد حدثنا مكي بن إبراهيم حدثنا الصلت بن دينار عن أبي نصرة عن جابر بن عبد الله قال قال رسول الله صلى الله عليه وسلم من أراد أن ينظر إلى شهيد يمشي على رجليه فلينظر إلى طلحة بن عبيد الله أخبرنا أبو الفضل المنصور بن أبي الحسن بن أبي عبد الله الطبري بإسناده عن أبي يعلى عن أبي كريب حدثنا يونس بن بكير عن طلحة بن يحيى عن موسى وعيسى ابني طلحة عن أبيهما أن أصحاب رسول الله صلى الله عليه وسلم قالوا لأعرابي جاء يسأله عمن قضى نحبه من هو قال فسأله الأعرابي فأعرض عنه سأله فأعرض عنه ثم سأله فأعرض عنه ثم إني اطلعت من باب المسجد وعلي ثياب خضر فلما رآني رسول الله صلى الله عليه وسلم قال أين السائل عمن قضى نحبه قال الأعرابي أنا يا رسول الله قال هذا ممن قضى نحبه وقتل طلحة يوم الجمل وكان شهد ذلك اليوم محاربا لعلي بن أبي طالب رضي الله عنهما فزعم بعض أهل العلم أن عليا دعاه فذكره أشياء من سوابقه على ما قال للزبير فرجع عن قتاله واعتزل في بعض الصفوف فرمي بسهم في رجله وقيل إن السهم أصاب ثغرة نحره فمات رماه مروان بن الحكم روى عبد الرحمن بن مهدي عن حماد بن زيد عن يحيى بن سعيد قال قال طلحة يوم الجمل

ندمت ندامة الكسعي لماشريت رضي بني جرم برغمي
اللهم خذ لعثمان مني حتى يرضى وإنما قال ذلك لأنه كان شديدا على عثمان رضي عنه وقال علي لما بلغه مسير طلحة والزبير وعائشة منيت بأربعة أدهى الناس وأسخاهم طلحة وأشجع الناس الزبير وأطوع الناس في الناس عائشة وأكثر الناس غنى يعلى بن منبه والله ما أنكروا على شيئا منكرا ولا استأثرت بمال ولا ملت بهوى وإنهم يطلبون حقا تركوه ودما سفكوه ولقد ولوه دوني وإن كنت شريكهم في الإنكار لما أنكروه وما تبعه عثمان إلا عندهم بايعوني ونكثوا بيعتي وما استبانوا في حتى يعرفوا جوري من عدلي وإني لراض بحجة الله عليهم وعلمه فيهم وإني مع هذا لداعيهم ومعذر إليهم فإن قبلوه فالتوبة مقبولة والحق أولى ما انصرف إليه وإن أبوا أعطيتهم حد السيف وكفى به شافيا من باطل وناصرا * وروى عن علي أنه قال إني لأرجو أن أكون أنا وطلحة وعثمان والزبير ممن قال الله فيهم ونزعنا ما في صدورهم من غل إخوانا على سرر متقابلين وكان سبب قتل طلحة أن مروان بن الحكم رماه بسهم في ركبته فجعلوا إذا أمسكوا فم الجرح انتفخت رجله وإذا تركوه جرى فقال دعوه فإنما هو سهم أرسله الله تعالى فمات منه وقال مروان لا أطلب بثأري بعد اليوم والتفت إلى أبان بن عثمان فقال قد كفيتك بعض قتلة أبيك ودفن إلى جانب الكلأ وكانت وقعة الجمل لعشر خلون من جمادى الآخر سنة ست وثلاثين وكان عمره ستين سنة وقيل اثنتان وستون وقيل أربع وستون سنة وكان آدم حسن الوجه كثير الشعر ليس بالجعد القطط ولا البسط وكان لا يغير شيبه وقيل كان أبيض يضرب إلى الحمرة مربوعا إلى القصر أقرب رحب الصدر عريض المنكبين إذا التفت التفت جميعا ضخم القدمين قال الشعبي لما قتل طلحة ورآه علي مقتولا جعل يمسح التراب عن وجهه وقال عزيز علي أبا محمد أن أراك مجدلا تحت نجوم السماء ثم قال إلى الله أشكو عجري وبجري وترحم عليه وقال ليتني مت قبل هذا اليوم بعشرين سنة وبكى هو وأصحابه عليه وسمع علي رجلا ينشد

فتى كان يدنيه الغنى من صديقهإذا ما هو استغنى ويبعده الفقر
فقال ذاك أبو محمد طلحة بن عبيد الله رحمه الله قال سفيان بن عيينة كانت غلة طلحة كل يوم ألفا وافيا قال الواقدي والوافي وزنه وزن الدينار هي وزن دراهم فارس التي تعرف بالبغلية وروى حماد بن سلمة عن علي بن زيد عن أبيه أن رجلا رأى في منامه أن طلحة بن عبيد الله قال حولوني عن قبري فقد آذاني الماء ثم رآه أيضا حتى رآه ثلاث ليال فأتى ابن عباس فأخبره فنظروا فإذا شقه الذي يلي الأرض قد اخضر من نز الماء فحولوه فكأني أنظر إلى الكافور في عينيه لم يتغير إلا عقيصته فإنها مالت عن موضعها فاشتروا له دارا من دور أبي بكر بعشرة آلاف درهم فدفنوه فيها أخبرنا عبد الله بن أحمد بن عبد القاهر أخبرنا أبو الخطاب بن النضر إجازة إن لم يكن سماعا 
حدثنا محمد بن أحمد بن رزق حدثنا مكرم بن أحمد القاضي حدثنا سعيد بن محمد أبو عثمان الأنجدابي حدثنا إبراهيم بن الفضل بن أبي سويد حدثنا حماد بن سلمة حدثنا علي بن زيد عن سعيد بن المسيب أن رجلا كان يقع في علي وطلحة والزبير فجعل سعد ابن مالك ينهاه ويقول لا تقع في إخواني فأبى فقام سعد فصلى ركعتين ثم قال اللهم إن كان مسخطا لك فيما يقول فأرني فيه آفة واجعله للناس آية فخرج الرجل فإذا هو ببختي يشق الناس فأخذه بالبلاط فوضعه بين كركرته والبلاط فسحقه حتى قتله فأنا رأيت الناس يتبعون سعدا ويقولون هنيئا لك أبا إسحاق أجيبت دعوتك أخرجه الثلاثة'
WHERE id = 38
  AND content_ar LIKE '(ب د ع) طلحة بن عبيد%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 38;


