UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'الزبير بن العوام بن خويلد بن أسد بن عبد العزى بن قصي بن كلاب بن مرة ابن كعب بن لؤي القرشي الأسدي يكنى أبا عبد الله أمه صفية بنت عبد المطلب عمة رسول الله صلى الله عليه وسلم فهو ابن عمة رسول الله وابن أخي خديجة بنت خويلد زوج النبي وكانت أمه تكنيه أبا الطاهر بكنية أخيها الزبير بن عبد المطلب واكتنى هو بأبي عبد الله بابنه عبد الله فغلبت عليه وأسلم وهو ابن خمس عشرة سنة قاله هشام بن عروة وقال عروة أسلم الزبير وهو ابن اثنتي عشرة سنة رواه أبو الأسود عن عروة وروى هشام بن عروة عن أبيه أن الزبير أسلم وهو ابن ست
عشرة سنة وقيل أسلم وهو ابن ثماني سنين وكان إسلامه بعد أبي بكر رضي الله عنه بيسير كان رابعا أو خامسا في الإسلام وهاجر إلى الحبشة وإلى المدينة وآخى رسول الله بينه وبين عبد الله بن مسعود لما آخى بين المهاجرين بمكة فلما قدم المدينة وآخى رسول الله بين المهاجرين والأنصار آخى بينه وبين سلمة بن سلامة بن وقش أخبرنا أبو ياسر عبد الوهاب بن أبي حبة بإسناده إلى عبد الله بن أحمد قال حدثني أبي أخبرنا زكرياء بن عدي أخبرنا علي بن مسهر عن هشام بن عروة عن أبيه عن مروان ولا أخا له يتهم علينا قال أصاب عثمان الرعاف سنة الرعاف حتى تخلف عن الحج وأوصى فدخل عليه رجل من قريش فقال استخلف قال وقالوه قال نعم قال من هو قال فسكت ثم دخل عليه رجل آخر فقال مثل ما قال الأول ورد عليه نحو ذلك قال فقال عثمان الزبير بن العوام قال نعم قال أما والذي نفسي بيده إن كان لأخيرهم ما علمت وأحبهم إلى رسول الله صلى الله عليه وسلم أخبرنا أبو الفداء إسماعيل بن عبيد الله وغير واحد بإسنادهم إلى أبي عيسى محمد بن عيسى بن سورة قال حدثنا هناد أخبرنا عبدة عن هشام بن عروة عن أبيه عن عبد الله بن الزبير عن الزبير قال جمع لي رسول الله صلى الله عليه وسلم أبويه يوم قريظة فقال بأبي وأمي قال وأخبرنا أبو عيسى أخبرنا أحمد بن منيع أخبرنا معاوية بن عمرو أخبرنا زائدة عن عاصم عن زر عن علي بن أبي طالب رضي الله عنه قال قال رسول الله صلى الله عليه وسلم أن لكل نبي حواريا وحواري الزبير بن العوام وروى عن جابر نحوه وقال أبو نعيم قاله رسول الله صلى الله عليه وسلم يوم الأحزاب لما قال من يأتينا بخبر القوم قال الزبير أنا قالها ثلاثا والزبير يقول أنا قال وأخبرنا أبو عيسى أخبرنا قتيبة أخبرنا حماد بن زيد عن صخر بن جويرية عن هشام بن عروة قال أوصى الزبير إلى ابنه عبد الله صبيحة الجمل فقال ما مني عضو إلا قد جرح مع رسول الله صلى الله عليه وسلم حتى انتهى ذلك إلى فرجه وكان الزبير أول من سل سيفا في الله عز وجل وكان سبب ذلك إن المسلمين لما كانوا مع النبي صلى الله عليه وسلم بمكة وقع الخبر أن النبي صلى الله عليه وسلم قد أخذه الكفار فأقبل الزبير يشق الناس بسيفه والنبي صلى الله عليه وسلم بأعلى مكة فقال له مالك يا زبير قال أخبرت أنك أخذت فصلى عليه النبي صلى الله عليه وسلم ودعا له ولسيفه وسمع ابن عمر رجلا يقول أنا ابن الحواري قال إن كنت ابن الزبير وإلا فلا وشهد الزبير بدرا وكان عليه عمامة صفراء معتجرا بها فيقال إن الملائكة نزلت يومئذ على سيما الزبير وشهد المشاهد كلها مع رسول الله صلى الله عليه وسلم أحدا والخندق والحديبية وخيبر والفتح وحنينا والطائف وشهد فتح مصر وجعله عمر بن الخطاب رضي الله عنهما في الستة أصحاب الشورى الذين ذكرهم للخلافة بعده وقال هم الذين توفي رسول الله صلى الله عليه وسلم وهو عنهم راض وهو أحد العشرة المشهود لهم بالجنة أخبرنا أبو البركات الحسن بن محمد بن الحسن بن هبة الله الدمشقي قال أخبرنا أبو العشائر محمد بن خليل بن فارس القيسي أخبرنا أبو القاسم علي بن محمد بن علي المصيصي أخبرنا أبو محمد عبد الرحمن بن عثمان بن القاسم بن أبي نصر أخبرنا أبو خيثمة خيثمة بن سليمان بن حيدرة أخبرنا أبو قلابة عبد الملك بن محمد الرقاشي أخبرنا محمد بن الصباح أخبرنا إسماعيل بن زكرياء عن النضر أبي عمر الجزاز عن عكرمة عن ابن عباس أن رسول الله صلى الله عليه وسلم لما انتفض حرا قال أسكن حرا فما عليك إلا نبي وصديق وشهيد وكان عليه النبي صلى الله عليه وسلم وأبو بكر وعمر وعثمان وعلي وطلحة والزبير وعبد الرحمن وسعد وسعيد بن زيد أخبرنا عبد الوهاب بن هبة الله بن عبد الوهاب بإسناده عن عبد الله بن أحمد حدثني أبي أخبرنا سفيان عن محمد بن عمرو بن علقمة عن يحيى بن عبد الرحمن بن حاطب عن عبد الله ابن الزبير بن العوام عن أبيه قال لما نزلت ثم لتسألن يومئذ عن النعيم قال الزبير يا رسول الله وأي النعيم نسأل عنه وإنما هما الأسودان التمر والماء قال أما إنه سيكون قيل كان للزبير ألف مملوك يؤدون إليه الخراج فما يدخل إلى بيته منها درهما واحدا وكان يتصدق بذلك كله ومدحه حسان ففضله على الجميع فقال

أقام على عهد النبي وهديهحواريه والقول بالفعل يعدلأقام على منهاجه وطريقهيوالي ولي الحق والحق أعدلهو الفارس المشهور والبطل الذييصول إذا ما كان يوم محجلوإن امرأ كانت صفية أمهومن أسد في بيته لمرفلله من رسول الله قربى قريبةومن نصرة الإسلام مجد مؤثلفكم كربة ذب الزبير بسيفهعن المصطفى والله يعطي ويجزلإذا كشفت عن ساقها الحرب حشهابأبيض سباق إلى الموت يرفل فما مثله فيهم ولا كان قبله * وليس يكون الدهر ما دام يذبل وقال هشام بن عروة أوصى إلى الزبير سبعة من أصحاب النبي صلى الله عليه وسلم 
منهم عثمان وعبد الرحمن بن عوف والمقداد وابن مسعود وغيرهم وكان يحفظ على أولادهم مالهم وينفق عليهم من ماله وشهد الزبير الجمل مقاتلا لعلي فناداه علي ودعاه فانفرد به وقال له أتذكر إذ كنت أنا وأنت مع رسول الله صلى الله عليه وسلم فنظر إلي وضحك وضحكت فقلت أنت لا يدع ابن أبي طالب زهوه فقال ليس بمزه ولتقاتلنه وأنت له ظالم فذكر الزبير ذلك فانصرف عن القتال فنزل بوادي السباع وقام يصلي فأتاه ابن جرموز فقتله وجاء بسيفه إلى علي فقال إن هذا سيف طالما فرج الكرب عن رسول الله صلى الله عليه وسلم ثم قال بشر قاتل ابن صفية بالنار وكان قتله يوم الخميس لعشر خلون من جمادي الأولى من سنة ست وثلاثين وقيل إن ابن جرموز استأذن على علي فلم يأذن له وقال للآذن بشره بالنار فقال

أتيت عليا برأس الزبيرأرجو لديه به الزلفهفبشر بالنار إذ جئتهفبئس البشارة والتحفهوسيان عندي قتل الزبيروضرطة عنز بذي الجحفه
وقيل إن الزبير لما فارق الحرب وبلغ سفوان أتى إنسان إلى الأحنف بن قيس فقال هذا الزبير قد لقي بسفوان فقال الأحنف ما شاء الله كان قد جمع بين المسلمين حتى ضرب بعضهم حواجب بعض بالسيوف ثم يلحق ببيته وأهله فسمعه ابن جرموز وفضالة بن حابس ونفيع بن غواة من تميم فركبوا فأتاه ابن جرموز من خلفه فطعنه طعنة خفيفة وحمل عليه الزبير وهو على فرس له يقال له ذو الخمار حتى إذا ظن أنه قاتله نادى صاحبيه فحملوا عليه فقتلوه وكان عمره لما قتل سبعا وستين سنة وقيل ستا وستين وكان أسمر ربعة معتدل اللحم خفيف اللحية وكثير من الناس يقولون أن ابن جرموز قتل نفسه لما قال له علي بشر قاتل ابن صفية بالنار وليس كذلك وإنما عاش بعد ذلك حتى ولي معصب بن الزبير البصرة فاختفى ابن جرموز فقال مصعب ليخرج فهو آمن أيظن أني أقيده بأبي عبد الله يعني أباه الزبير ليسا سواء فظهرت المعجزة بأنه من أهل النار لأنه قتل الزبير رضي الله عنه وقد فارق المعركة وهذه معجزة ظاهرة أخرجه الثلاثة'
WHERE id = 39
  AND content_ar LIKE '(ب د ع) الزبير بن ال%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 39;


