UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'سعد بن مالك وهو سعد بن أبي وقاص واسم أبي وقاص مالك بن وهيب وقيل أهيب بن عبد مناف بن زهرة بن كلاب بن مرة بن كعب بن لؤي بن غالب ابن فهر بن النضر بن كنانة القرشي الزهري يكنى أبا إسحاق وأمه حمنة بنت سفيان بن أمية بن عبد شمس وقيل حمنة بنت أبي سفيان بن أمية أسلم بعد ستة وقيل بعد أربعة وكان عمره لما أسلم سبع عشرة سنة روى عنه أنه قال أسلمت قبل أن تفرض الصلاة وهو أحد الذين شهد لهم رسول الله صلى الله عليه وسلم بالجنة وأحد العشرة سادات الصحابة وأحد الستة أصحاب الشورى الذين أخبر عمر بن الخطاب رضي الله عنه أن رسول الله صلى الله عليه وسلم توفي وهو عنهم راض شهد بدرا وأحدا والخندق والمشاهد كلها مع رسول الله صلى الله عليه وسلم أبلى يوم أحد بلاء عظيما وهو أول من أراق دما في سبيل الله وأول من رمي بسهم في سبيل الله أخبرنا أبو الفرج بن أبي الرجاء بن سعد قال أخبرنا أبو علي قراءة عليه وأنا حاضر أسمع أخبرنا أبو نعيم أحمد بن عبد الله أخبرنا أبو محمد عبد الله بن جعفر الجابري أخبرنا محمد بن أحمد بن المثنى أخبرنا جعفر بن عون أخبرنا إسماعيل بن أبي خالد عن قيس قال سمعت سعدا يقول إني لأول العرب رمى بسهم في سبيل الله والله إن كنا لنغزو مع رسول الله صلى الله عليه وسلم ما لنا طعام إلا ورق الحبلة وهذا السمر حتى إن أحدنا ليضع كما تضع الشاة ماله خلط ثم أصبحت بنو أسد تعزرني على الدين لقد خبت إذا وضل عملي وكان ناس من أهل الكوفة شكوه إلى عمر بن الخطاب فعزله عن الكوفة وكان أكثرهم شكوى منه رجل من بني أسد وأخبرنا أبو
إسحاق إبراهيم بن محمد بن مهران وغير واحد بإسنادهم إلى أبي عيسى محمد بن عيسى قال حدثنا أبو كريب وأبو سعيد الأشج قالا أخبرنا أبو أمامة عن مجالد عن عامر عن جابر قال أقبل سعد فقال رسول الله صلى الله عليه وسلم هذا خالي فليرني امرؤ خاله وإنما قال هذا لأن سعد أزهري وأم رسول الله صلى الله عليه وسلم زهرية وهو ابن عمها فإنها آمنة بنت وهب بن عبد مناف بن زهرة يجتمعان في عبد مناف وأهل الأم أخوال وأخبرنا أبو جعفر عبيد الله بن أحمد بن علي بإسناده عن يونس بن بكير عن ابن إسحاق قال كان أصحاب رسول الله صلى الله عليه وسلم إذا صلوا ذهبوا إلى الشعاب فاستخفوا بصلاتهم من قومهم فبينا سعد بن أبي وقاص في نفر من أصحاب رسول الله صلى الله عليه وسلم في شعب من شعاب مكة إذ ظهر عليهم نفر من المشركين فناكروهم وعابوا عليهم دينهم حتى قاتلوهم فاقتتلوا فضرب سعد رجلا من المشركين بلحي جمل فشجه فكان أول دم أهريق في الإسلام واستعمل عمر بن الخطاب سعدا على الجيوش الذين سيرهم لقتال الفرس وهو كان أمير الجيش الذين هزموا الفرس بالقادسية وبجلولا أرسل بعض الذين عنده فقاتلوا الفرس بجلولا فهزموهم وهو الذي فتح المدائن مدائن كسرى بالعراق وهو الذي بنى الكوفة وولى العراق ثم عزله فلما حضرت عمر الوفاة جعله أحد أصحاب الشورى وقال إن ولي سعد الإمارة فذاك وإلا فأوصي الخليفة بعدي أن يستعمله فإني لم أعزله من عجز ولا خيانة فولاه عثمان الكوفة ثم عزله واستعمل الوليد بن عقبة بن أبي معيط أخبرنا إسماعيل بن علي وغير واحد بإسنادهم إلى محمد بن عيسى بن سورة قال حدثنا رجا بن محمد العدوي أخبرنا جعفر بن عون عن إسماعيل بن أبي خالد عن قيس بن أبي حازم عن سعد أن رسول الله صلى الله عليه وسلم قال اللهم استجب لسعد إذا دعاك وكان لا يدعو إلا استجيب له وكان الناس يعلمون ذلك منه ويخافون دعاءه قال وأخبرنا محمد بن عيسى أخبرنا الحسن بن الصباح البزاز أخبرنا سفيان بن عيينة عن علي بن زيد ويحيى بن سعيد سمعا ابن المسيب يقول قال علي بن أبي طالب ما جمع رسول الله صلى الله عليه وسلم أباه وأمه لأحد إلا لسعد بن أبي وقاص قال له يوم أحد ارم فداك أبي وأمي ارم أيها الغلام الحزور وقد روي أنه جمعهما للزبير بن العوام أيضا قال الزهري رمى سعد يوم أحد ألف سهم ولما قتل عثمان اعتزل الفتنة ولم يكن مع أحد من الطوائف المتحاربة بل لزم بيته وأراد ابنه عمر وابن أخيه هاشم بن عتبة بن أبي وقاص أن يدعو إلى نفسه بعد قتل عثمان فلم يفعل وطلب السلامة فلما اعتزل طمع فيه معاوية وفي عبد الله بن عمر وفي محمد بن مسلمة فكتب إليهم يدعوهم إلى أن يعينوه على الطلب بدم عثمان ويقول إنكم لا تكفرون ما أتيتموه من خذلانه إلا بذلك فأجابه كل وأحسد منهم يرد عليه ما جاء به وكتب إليه سعد أبيات شعر

معاوي داؤك الداء العياءوليس لما تجئ به دواءأيدعوني أبو حسن عليفلم أردد عليه ما يشاءوقلت له اعطني سيفا قصيراتميز به العداوة والولاءأتطمع في الذي أعيا علياعلى ما قد طمعت به العفاءليوم منه خير منك حياوميتا أنت للمرء الفداء
وروت عنه ابنته عائشة أنه قال رأيت في المنام قبل أن سلم كأني في ظلمة لا أبصر شيئا إذ أضاء لي قمر فاتبعته فكأني أنظر إلى من سبقني إلى ذلك القمر فأنظر إلى زيد بن حارثة وإلى علي بن أبي طالب وإلى أبي بكر وكأني أسألهم متى انتهيتم إلى هاهنا قالوا الساعة وبلغني أن رسول الله صلى الله عليه وسلم يدعو إلى الإسلام مستخفيا فلقيته في شعب أجياد وقد صلى العصر فأسلمت فما تقدمني أحد إلا هم وروى داود ابن أبي هند عن أبي عثمان النهدي أن سعد بن أبي وقاص قال نزلت هذه الآية في وإن جاهداك على أن تشرك بي ما ليس لك به علم فلا تطعهما وصاحبهما في الدنيا معروفا قال كنت رجلا برا بأمي فلما أسلمت قالت يا سعد ما هذا الدين الذي أحدثت لتدعن دينك هذا أو لا آكل ولا أشرب حتى أموت فتعير بي فقال لا تفعلي يا أمه فإني لا أدع ديني قال فمكثت يوما وليلة لا تأكل فأصبحت وقد جهدت فقلت والله لو كانت لك ألف نفس فخرجت نفسا نفسا ما تركت ديني هذا لشئ فلما رأت ذلك أكلت وشربت فأنزل الله هذه الآية قال أبو المنهال سأل عمر بن الخطاب عمرو بن معدي كرب عن خبر سعد بن أبي وقاص فقال متواضع في خبائه عربي في نمرته أسد في تاموره يعدل في القضية ويقسم بالسوية ويبعد في السرية ويعطف علينا عطف الأم البرة وينقل إلينا حقنا نقل الذرة وروى سعد عن النبي صلى الله عليه وسلم أحاديث كثيرة روى عنه ابن عمر وابن عباس وجابر بن سمرة والسائب بن يزيد وعائشة وبنوه عامر ومصعب ومحمد وإبراهيم وعائشة أولا سعد وابن المسيب وأبو عثمان 
النهدي وإبراهيم بن عبد الرحمن بن عوف وقيس بن أبي حازم وغيرهم أخبرنا أبو البركات الحسن بن محمد بن هبة الله الشافعي الدمشقي أخبرنا أبو العشائر محمد بن الخليل بن فارس القيسي أخبرنا أبو القاسم علي بن محمد بن علي بن أبي العلاء المصيصي أخبرنا أبو محمد عبد الرحمن بن عثمان بن أبي نصر أخبرنا أبو إسحاق إبراهيم ابن محمد بن أحمد بن أبي ثابت حدثنا يزيد بن محمد بن عبد الصمد أخبرنا عبد الله بن يزيد أخبرنا صدقة عن عياض بن عبد الرحمن عن موسى بن عقبة عن عامر بن سعد بن أبي وقاص قال قلت لأبي يا أبت إني أراك تصنع بهذا الحي من الأنصار شيئا ما تصنعه بغيرهم فقال أي بني هل تجد في نفسك من ذلك شيئا قال لا ولكن أعجب من صنيعك قال إني سمعت رسول الله صلى الله عليه وسلم يقول لا يحبهم إلا مؤمن ولا يبغضهم إلا منافق وتوفي سعد بن أبي وقاص سنة خمس وخمسين قاله الواقدي وقال أبو نعيم الفضل بن دكين مات سنة ثمان وخمسين وقال الزبير وعمرو بن علي والحسن ابن عثمان توفي سعد سنة أربع وخمسين وقال إسماعيل بن محمد بن سعد كان سعد آدم طويلا أفطس وقيل كان قصيرا دحداحا غليظا ذا هامة شثن الأصابع قالته ابنته عائشة وتوفي بالعقيق على سبعة أميال من المدينة فحمل على أعناق الرجال إلى المدينة فأدخل المسجد فصلى عليه مروان وأزواج النبي صلى الله عليه وسلم قال ابنه عامر كان سعد آخر المهاجرين موتا ولما حضرته الوفاة دعا بخلق جبة له من صوف فقال كفنوني فيها فإني كنت لقيت المشركين فيها يوم بدر وهي علي وإنما كنت أخبؤها لهذا أخرجه الثلاثة * حازم بالحاء المهملة والزاي الحبلة ثمر السمر وقيل ثمر العضاه يشبه اللوبياء التامور عرين الأسد وهو بيته الذي يأوي إليه'
WHERE id = 41
  AND content_ar LIKE '(ب د ع) سعد بن مالك %'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 41;

-- id=42  سعيد بن زيد
SELECT id, source_codes, left(content_ar, 60) AS content_preview
