BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'سعيد بن زيد بن عمرو بن نفيل بن عبد العزى ابن رياح بن عبد الله بن قرظ بن رزاح بن عدي بن كعب بن لؤي القرشي العدوي وهو ابن عم عمر بن الخطاب يجتمعان في نفيل أمه فاطمة بنت بعجة بن مليح الخزاعية وكان صهر عمر زوج أخته فاطمة بنت الخطاب وكانت أخته عاتكة بنت زيد تحت عمر بن الخطاب تزوجها بعد أن قتل عنها عبد الله بن أبي بكر الصديق رضي الله عنهم وكان سعيد يكنى أبا الأعور وقيل أبا ثور والأول أكثر أسلم قديما قبل عمر بن الخطاب هو وامرأته فاطمة بنت الخطاب وهي كانت سبب إسلام عمر على ما نذكره في ترجمته أن شاء الله تعالى وكان من المهاجرين الأولين وآخى رسول الله صلى الله عليه وسلم بينه وبين أبي بن كعب ولم يشهد بدرا وضرب له رسول الله صلى الله عليه وسلم بسهمه وأجره فقيل إنما لم يشهدها لأنه كان غائبا بالشام فقدم عقيب غزاة بدر فضرب له رسول الله صلى الله عليه وسلم بسهمه وأجره قاله موسى بن عقبة وابن
إسحاق وقال الواقدي كان رسول الله صلى الله عليه وسلم قد بعث قبل أن يخرج إلى بدر طلحة بن عبيد الله وسعيد بن زيد إلى طريق الشام يتجسسان الأخبار ثم رجعا إلى المدينة فقدماها يوم الوقعة ببدر فضرب لهما رسول الله صلى الله عليه وسلم بسهمهما وأجرهما وقال الزبير مثله وقد قيل إنه شهد بدرا والأول أصح وشهد ما بعدها من المشاهد وهو أحد العشرة المشهود لهم بالجنة أخبرنا أبو بكر محمد بن عبد الوهاب بن عبد الله بن علي الأنصاري الدمشقي والقاضي أبو نصر عبد الرحيم ابن محمد بن الحسن بن هبة الله وغيرهما قالوا أخبرنا الحافظ أبو القاسم علي بن الحسن بن هبة الله الدمشقي الشافعي أخبرنا القاضي أبو عبد الله الحسين بن أحمد ابن علي البيهقي أخبرنا لقاضي أبو علي محمد بن إسماعيل بن محمد العراقي أخبرنا أبو طاهر محمد بن عبد الرحمن بن العباس المخلص أخبرنا أبو القاسم البغوي أخبرنا يحيى بن عبد الحميد الحماني حدثنا الدراوردي أخبرنا عبد الرحمن بن حميد بن عبد الرحمن بن عوف عن أبيه حميد عن جده عبد الرحمن بن عوف قال قال رسول الله صلى الله عليه وسلم أبو بكر في الجنة وعمر في الجنة وعثمان في الجنة وعلي في الجنة وطلحة في الجنة والزبير في الجنة وعبد الرحمن بن عوف في الجنة وسعد بن أبي وقاص في الجنة وسعيد بن زيد في الجنة وأبو عبيدة بن الجراح في الجنة وروى عن سعيد بن زيد مثله أخبرنا أبو الفضل عبد الله بن أحمد الخطيب بإسناده إلى أبي داود الطيالسي أخبرنا إبراهيم بن سعد عن أبيه عن أبي عبيدة بن محمد بن عمار بن ياسر عن طلحة بن عبد الله بن عوف عن سعيد بن زيد أن رسول الله صلى الله عليه وسلم قال من قتل دون ماله فهو شهيد وكان مجاب الدعوة فمن ذلك أن أروى بنت أويس شكته إلى مروان بن الحكم وهو أمير المدينة لمعاوية وقالت إنه ظلمني أرضي فأرسل إليه مروان فقال سعيد أتروني ظلمتها وقد سمعت رسول الله صلى الله عليه وسلم يقول من ظلم شبرا من أرض طوقه يوم القيامة من سبع أرضين اللهم إن كانت كاذبة فلا تمتها حتى تعمي بصرها وتجعل قبرها في بئرها فلم تمت حتى ذهب بصرها وجعلت تمشي في دارها فوقعت في بئرها فكانت قبرها فال فكان أهل المدينة يقولون أعماك الله كما أعمى أروى يريدونها ثم صار أهل الجهل يقولون أعماك الله كما أعمى الأروى يريدون الأروى التي في الجبل يظنونها ويقولون إنها عمياء وهذا جهل منهم * وشهد اليرموك وحصار دمشق روى عنه ابن عمر وعمرو بن 
حريث وأبو الطفيل وعبد الله بن ظالم المازني وزر بن حبيش وأبو عثمان النهدي وعروة بن الزبير وأبو سلمة بن عبد الرحمن وغيرهم أخبرنا عبد الوهاب بن هبة الله ابن عبد الوهاب بإسناده إلى عبد الله بن أحمد حدثني أبي أخبرنا معاوية بن عمرو أخبرنا زايدة أخبرنا حصين بن عبد الرحمن عن هلال بن يساف عن عبد الله بن ظالم التميمي عن سعيد بن زيد بن عمرو بن نفيل قال أشهد أن عليا من أهل الجنة قلت وما ذاك قال هو في التسعة ولو شئت أن أسمي العاشر لسميته قال اهتز حراء فقال رسول الله صلى الله عليه وسلم اثبت حراء فإنه ليس عليك إلا نبي أو صديق أو شهيد قال ورسول الله وأبو بكر وعمر وعثمان وعلي وطلحة والزبير وعبد الرحمن بن عوف وسعد وأنا يعني نفسه * وقال سعيد بن جبير كان مقام أبي بكر وعمر وعثمان وعلي وطلحة والزبير وسعد وعبد الرحمن بن عوف وسعيد بن زيد كانوا أمام رسول الله صلى الله عليه وسلم في القتال ووراءه في الصلاة وتوفي سعيد بن زيد سنة خمسين أو إحدى وخمسين وهو ابن بضع وسبعين سنة وقيل توفي سنة ثمان وخمسين بالعقيق من نواحي المدينة وقيل توفي بالمدينة والأول أصح وخرج إليه عبد الله بن عمر فغسله وحنطه وصلى عليه قال نافع وقالت عائشة بنت سعد غسل سعيد بن زيد سعد بن أبي وقاص وحنطه ثم أتى البيت فاغتسل فلما خرج قال أما إني لم اغتسل من غسلي إياه ولكن أغتسل من الحر ونزل في قبره سعد بن أبي وقاص وابن عمر وصلى عليه ابن عمر أخرجه الثلاثة'
WHERE id = 42
  AND content_ar LIKE '(ب د ع) سعيد بن زيد %'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 42;


